import React, { Component } from "react";
import "./Header.css";
import MenuJson from '../MenuJson';

export default class Header extends Component {
  constructor(props) {
    super(props);
    this.state = {
        headerdata: null,
    };
}
componentDidMount() {
      this.fetchHeader1Menu();

}

fetchHeader1Menu=()=>{
        fetch(`http://localhost:3001/menu_pages_connection/1`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({})
        }) 
        .then(response => response.json())
        .then(data => {
            this.setState({ contactuspage : data });
        })
        .catch(error => console.error('Error fetching data:', error));

    }

    fetchHeader2Menu=()=>{
      fetch(`http://localhost:3001/menu_pages_connection/2`, {
          method: 'POST',
          headers: {
              'Content-Type': 'application/json'
          },
          body: JSON.stringify({})
      }) 
      .then(response => response.json())
      .then(data => {
          this.setState({ contactuspage : data });
      })
      .catch(error => console.error('Error fetching data:', error));

  }
  render() {
    return (
      <div>
        <nav>
          <ul>
            <li><h1 className="logo" ><a herf="/Homepage" >{MenuJson[8].text}</a></h1></li>
          </ul>

          <ul>
            {MenuJson.filter(menuItem => menuItem.menuId === 1).map(headerMenu => (
              <li>
                <a className={headerMenu.style} href={headerMenu.url}>{headerMenu.text}</a>
              </li>
            ))}
          </ul>
        </nav>

        <div className="orange-navbar">
          <div className="navcontainer">
            {MenuJson.filter(menuItem => menuItem.menuId === 2).map(headerMenu => (
              <li>
                <a className={headerMenu.style} href={headerMenu.url}>{headerMenu.text}</a>
              </li>
            ))}
          </div>
        </div>
      </div>
    );
  }
}
